// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address caller, uint256 newTimestamp) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));

        uint256 pay = 10 ether;
        vm.deal(caller, pay);

        vm.assume(newTimestamp > block.timestamp);
        vm.warp(newTimestamp);

        vm.prank(caller);
        (bool ok, ) = address(c).call{value: pay}("");
        require(ok, "fallback call failed");

        assertTrue(c.pastBlockTime() == newTimestamp);
    }
}
